const emergency = msg.payload.emergency === true;
const fire = (msg.payload.last_emergency_reason || '').toLowerCase() === 'fire';
if (emergency && fire) {
    msg.payload = '<div class="st-top-banner"><span class="st-top-banner__ico">!</span><span class="st-top-banner__txt">UYARI: Yangin Algilandi! Tahliye Islemlerini Baslatin.</span><span class="st-top-banner__link">AYRINTILAR</span></div>';
} else {
    msg.payload = '<div class="st-top-banner st-top-banner--hidden"></div>';
}
return msg;

const p = msg.payload;
if (p && typeof p.occupancy === 'number' && p.updated_at) {
    flow.set('lastState', p);
}
const st = flow.get('lastState') || {
    occupancy: 0,
    emergency: false,
    last_emergency_reason: '',
    last_event_type: 'idle',
    fire_temp_on_c: 60,
    fire_temp_off_c: 55,
    fire_temp_on_debounce_sec: 0,
    fire_temp_off_debounce_sec: 0,
    room_capacity: 10,
};
let temp = Number(st.temperature_c);
if (Number.isNaN(temp)) {
    temp = Number(flow.get('currentTemperatureC'));
    if (Number.isNaN(temp)) {
        temp = 0;
    }
}
const occ = st.occupancy ?? 0;
const emergency = st.emergency === true;
const reason = (st.last_emergency_reason || '').toLowerCase();
const hasFire = emergency && reason === 'fire';
const cap = Math.max(Number(st.room_capacity ?? 10), 1);
const pct = Math.min(100, Math.round((occ / cap) * 100));
const onC = Number(st.fire_temp_on_c ?? 60);
const offC = Number(st.fire_temp_off_c ?? 55);
const onDb = Number(st.fire_temp_on_debounce_sec ?? 0);
const offDb = Number(st.fire_temp_off_debounce_sec ?? 0);
const fireStatus = hasFire ? 'Yangin Var' : 'Yangin Yok';
const fireBadge = hasFire ? 'TEHLIKE' : 'GUVENLI';
const fireBadgeClass = hasFire ? 'danger' : 'safe';
const dotClass = hasFire ? 'st-dot st-dot--hot' : 'st-dot';
const tempNote = temp >= onC ? 'Yuksek sicaklik' : 'Normal aralikta';
const thrHtml = '<div class="st-thr-line"><span>ON</span><b>' + onC.toFixed(1) + ' C</b><span>/ ' + onDb + 's</span></div>'
    + '<div class="st-thr-line"><span>OFF</span><b>' + offC.toFixed(1) + ' C</b><span>/ ' + offDb + 's</span></div>';
const html = '<div class="st-metrics-grid">'
    + '<div class="st-metric"><div class="st-metric-label">YANGIN DURUMU</div><div class="st-metric-body">'
    + '<span class="' + dotClass + '"></span><span class="st-metric-main">' + fireStatus + '</span>'
    + '<span class="st-badge st-badge--' + fireBadgeClass + '">' + fireBadge + '</span></div></div>'
    + '<div class="st-metric"><div class="st-metric-label">ANLIK SICAKLIK</div><div class="st-metric-body st-metric-body--temp">'
    + '<span class="st-metric-big">' + temp.toFixed(1) + '&deg;C</span><span class="st-metric-sub">' + tempNote + '</span></div></div>'
    + '<div class="st-metric"><div class="st-metric-label">ODA DOLULUK</div><div class="st-metric-body" style="flex-direction:column;align-items:stretch">'
    + '<span class="st-metric-big">' + occ + ' kisi</span><div class="st-bar"><i style="width:' + pct + '%"></i></div></div></div>'
    + '<div class="st-metric"><div class="st-metric-label">ESIK AYARLARI</div><div class="st-metric-body st-thr">' + thrHtml + '</div></div>'
    + '</div>';
msg.payload = html;
return msg;

const temp = Number(msg.payload?.temperature_c ?? msg.payload?.temperature);
if (Number.isNaN(temp)) {
    return null;
}
flow.set('currentTemperatureC', temp);
let st = flow.get('lastState');
if (!st) {
    st = {
        occupancy: 0,
        emergency: false,
        last_emergency_reason: '',
        last_event_type: 'idle',
        fire_temp_on_c: 60,
        fire_temp_off_c: 55,
        fire_temp_on_debounce_sec: 0,
        fire_temp_off_debounce_sec: 0,
        room_capacity: 10,
    };
}
msg.payload = st;
return msg;

const timestamp = new Date().toISOString();
flow.set('currentTemperatureC', 0);
const prev = flow.get('lastState') || {};
const baselineState = {
    room_capacity: prev.room_capacity ?? 10,
    occupancy: 0,
    emergency: false,
    last_emergency_reason: '',
    last_event_type: 'reset',
    last_event_source: 'dashboard',
    last_event_confidence: 1,
    updated_at: timestamp,
    fire_temp_on_c: prev.fire_temp_on_c ?? 60,
    fire_temp_off_c: prev.fire_temp_off_c ?? 55,
    fire_temp_on_debounce_sec: prev.fire_temp_on_debounce_sec ?? 0,
    fire_temp_off_debounce_sec: prev.fire_temp_off_debounce_sec ?? 0,
};
flow.set('lastState', baselineState);
const resetControl = {
    topic: 'building/room1/control',
    payload: {
        event_type: 'reset',
        timestamp,
        room_id: 'room1',
        source: 'dashboard',
        confidence: 1.0,
    },
};
const resetTemperatureTelemetry = {
    topic: 'building/room1/telemetry',
    payload: {
        temperature_c: 0,
        timestamp,
        room_id: 'room1',
        source: 'dashboard_reset',
        confidence: 1.0,
    },
};
const resetOccupancyChart = {
    topic: 'Doluluk',
    payload: [],
};
const resetHistory = {
    payload: true,
};
const bannerMsg = { payload: '<div class="st-top-banner st-top-banner--hidden"></div>' };
const metricsMsg = { payload: baselineState };
return [resetControl, resetTemperatureTelemetry, metricsMsg, resetOccupancyChart, resetHistory, bannerMsg];

const action = msg.payload?.action || '';
const step = Number(msg.payload?.step || 5);
let currentTemp = Number(flow.get('currentTemperatureC') ?? 0);
if (Number.isNaN(currentTemp)) {
    currentTemp = 0;
}
if (action === 'temp_up') {
    currentTemp += step;
} else if (action === 'temp_down') {
    currentTemp -= step;
} else {
    return null;
}
currentTemp = Math.max(currentTemp, 0);
flow.set('currentTemperatureC', currentTemp);
const timestamp = new Date().toISOString();
const telemetryMsg = {
    topic: 'building/room1/telemetry',
    payload: {
        temperature_c: currentTemp,
        timestamp,
        room_id: 'room1',
        source: 'dashboard_temperature_button',
        confidence: 1.0,
    },
};
let st = flow.get('lastState');
if (!st) {
    st = {
        occupancy: 0,
        emergency: false,
        last_emergency_reason: '',
        last_event_type: 'idle',
        fire_temp_on_c: 60,
        fire_temp_off_c: 55,
        fire_temp_on_debounce_sec: 0,
        fire_temp_off_debounce_sec: 0,
        room_capacity: 10,
    };
}
return [telemetryMsg, { payload: st }];

const action = msg.payload?.action || '';
const count = Number(msg.payload?.count || 1);
const roomId = 'room1';

const mk = (eventType, topic) => ({
    topic,
    payload: {
        event_type: eventType,
        timestamp: new Date().toISOString(),
        room_id: roomId,
        source: 'dashboard_quick_action',
        confidence: 1.0,
    },
});

if (action === 'entries') {
    for (let i = 0; i < count; i++) {
        node.send(mk('entry', 'building/room1/entry'));
    }
    return null;
}

if (action === 'exits') {
    for (let i = 0; i < count; i++) {
        node.send(mk('exit', 'building/room1/exit'));
    }
    return null;
}

if (action === 'fire') {
    return mk('fire', 'building/room1/emergency');
}

return null;

const labelMap = {
    fire: 'Sicaklik Esigi Asildi',
    reset: 'Sicaklik Normallesti',
    exit: 'Kisi Cikisi',
    entry: 'Kisi Girisi',
    idle: 'Beklemede',
    inactivity: 'Hareketsizlik',
};
let history = flow.get('eventHistory') || [];
const st = msg.payload;
const updatedAt = st.updated_at
    ? new Date(st.updated_at).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit', second: '2-digit', timeZone: 'Europe/Istanbul' })
    : '-';
const eventType = (st.last_event_type || 'idle').toLowerCase();
const occ = st.occupancy ?? 0;
const emg = st.emergency === true;
let evLabel = labelMap[eventType] || eventType;
if (eventType === 'exit' && occ === 0) {
    evLabel = 'Oda Terk Edildi';
}
const entry = {
    t: updatedAt,
    ev: evLabel,
    occ,
    emg,
};
const sig = entry.t + '|' + entry.ev + '|' + entry.occ + '|' + (entry.emg ? '1' : '0');
const last = history[history.length - 1];
const lastSig = last ? last.sig : '';
if (!last || lastSig !== sig) {
    entry.sig = sig;
    history.push(entry);
}
if (history.length > 20) {
    history = history.slice(history.length - 20);
}
flow.set('eventHistory', history);
const rev = history.slice().reverse();
let table = '<table class="st-hist"><thead><tr><th>SAAT</th><th>OLAY</th><th>DOLULUK</th><th>ACIL DURUM</th></tr></thead><tbody>';
rev.forEach((r) => {
    const badge = r.emg
        ? '<span class="st-badge st-badge--emg">AKTIF</span>'
        : '<span class="st-badge st-badge--passive">PASIF</span>';
    table += '<tr><td>' + r.t + '</td><td>' + r.ev + '</td><td>' + r.occ + ' kisi</td><td>' + badge + '</td></tr>';
});
table += '</tbody></table>';
msg.payload = table;
return msg;
